-- Texte der Ortsseiten (Plan docs/plan-locations-2026-11-18.md, 3.14, Schritt 4)
-- Erzeugt am 2026-11-20 von `python -m scraper.orte.spielstaetten_texte --sql` aus data/spielstaetten/texte.csv
-- (nur Zeilen mit freigabe = ja und ohne Prüffehler). Jeder Satz hat eine Quelle (extras.spielstaette.
-- text_freigegeben.quellen). Absätze per Leerzeile, **fett** zeigt die Ortsseite. Wiederholbar.

BEGIN;

UPDATE public.orte SET beschreibung = $txt$Das **Capitol Theater** an der Erkrather Straße ist eine Bühne für Musicals, Shows, Comedy und Veranstaltungen. Es wurde Anfang der 1990er-Jahre in einem über 100 Jahre alten ehemaligen **Straßenbahndepot** der Rheinbahn eingerichtet. Nach Angaben des Hauses eröffnete es **1996** mit dem Musical „Grease“.

Bei einer Renovierung im Jahr 1999 blieben die **Backsteinarchitektur** und der Charakter des Depots erhalten. Der große **Theatersaal** hat 1.250 Plätze und eine 25 mal 13 Meter große Bühne. Als zweiter Saal fasst der **Club** bis zu 475 Gäste in Theaterbestuhlung. Hinzu kommt ein über 1.000 Quadratmeter großes Foyer mit Wintergarten.

Im Jahr 2011 zog der **Quatsch Comedy Club** dauerhaft ins Capitol ein. Betreiberin des Hauses ist die **ATG Entertainment GmbH**.$txt$, webseite = COALESCE(webseite, 'https://www.capitol-theater.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.capitol-theater.de/", "https://en.wikipedia.org/wiki/Capitol_Theater_(Düsseldorf)", "https://www.capitol-theater.de/", "https://de.wikipedia.org/wiki/Capitol_Theater_(Düsseldorf)", "https://www.capitol-theater.de/", "https://www.capitol-theater.de/", "https://www.capitol-theater.de/", "https://www.capitol-theater.de/", "https://www.capitol-theater.de/"]}}'::jsonb)
WHERE slug = 'capitol-theater' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Düsseldorfer Schauspielhaus**, kurz D’haus, ist ein Ensembletheater mit Hauptspielstätte am **Gustaf-Gründgens-Platz**. Louise Dumont und Gustav Lindemann eröffneten **1905** an der Karl-Theodor-Straße das Schauspielhaus Düsseldorf als Privattheater. Dem Haus war eine Theaterakademie angeschlossen, zu deren Schülern Gustaf Gründgens gehörte. Von 1951 bis 1970 spielte das Schauspielhaus an der Jahnstraße.

Das heutige Gebäude entwarf der Düsseldorfer Architekt **Bernhard Pfau**, es entstand von 1965 bis 1969 und wurde im Januar 1970 mit Büchners „Dantons Tod“ eröffnet. Die skulpturale Großform steht in deutlichem Kontrast zum benachbarten **Dreischeibenhaus**. In den Spielzeiten 2016/17 bis 2018/19 wurde das Haus umfassend saniert.

Im Gebäude liegen das Große Haus mit rund 730 Plätzen, das Kleine Haus mit bis zu 300 Plätzen und das **Unterhaus**, eine experimentelle Spielstätte im Keller. Junges Schauspiel und Stadt:Kollektiv spielen im **Central** an der Worringer Straße am Hauptbahnhof, das zugleich Proben- und Produktionszentrum ist. Nahe Haltestellen sind Schadowstraße, Heinrich-Heine-Allee und Jacobistraße.$txt$, webseite = COALESCE(webseite, 'https://www.dhaus.de'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/D%C3%BCsseldorfer_Schauspielhaus", "https://www.dhaus.de/das-dhaus/ueber-das-haus/", "https://www.dhaus.de/das-dhaus/ueber-das-haus/", "https://www.dhaus.de/das-dhaus/ueber-das-haus/", "https://de.wikipedia.org/wiki/D%C3%BCsseldorfer_Schauspielhaus", "https://de.wikipedia.org/wiki/D%C3%BCsseldorfer_Schauspielhaus", "https://www.dhaus.de/das-dhaus/ueber-das-haus/", "https://www.dhaus.de/das-dhaus/ueber-das-haus/", "https://www.dhaus.de/das-dhaus/ueber-das-haus/", "https://www.dhaus.de/besuch/anreise/"]}}'::jsonb)
WHERE slug = 'duesseldorfer-schauspielhaus' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Filmmuseum Düsseldorf** ist ein städtisches Museum in der **Altstadt** am Alten Hafen. Bereits 1979 gründete die Stadt ein Filminstitut, das Museumsgebäude an der Schulstraße wurde am **21. August 1993** eröffnet. Die Dauerausstellung zeigt auf rund 2.200 Quadratmetern die Geschichte des Films von den Anfängen bis in die Gegenwart.

Zur Sammlung gehören unter anderem rund 500.000 Fotos, mehr als 25.000 Plakate und Nachlässe etwa von **Lotte Reiniger** und Helmut Käutner. Als einziges Museum dieser Art in Nordrhein-Westfalen beherbergt das Haus die **Filmsammlung des Landes**, das Archiv umfasst über 30.000 Filmkopien.

Im Haus liegt das Kino **Black Box** mit 135 Plätzen, das seit 2009 als kommunales Kino betrieben wird. Gezeigt werden Klassiker, Retrospektiven und Neuerscheinungen, viele Vorführungen laufen von analogen Kopien. Im Kino steht außerdem eine **Welte-Kinoorgel** aus dem Jahr 1928.$txt$, webseite = COALESCE(webseite, 'https://www.duesseldorf.de/filmmuseum'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Filmmuseum_Düsseldorf", "https://de.wikipedia.org/wiki/Filmmuseum_Düsseldorf", "https://www.duesseldorf.de/filmmuseum", "https://de.wikipedia.org/wiki/Filmmuseum_Düsseldorf", "https://www.duesseldorf.de/filmmuseum", "https://de.wikipedia.org/wiki/Filmmuseum_Düsseldorf", "https://de.wikipedia.org/wiki/Filmmuseum_Düsseldorf", "https://de.wikipedia.org/wiki/Filmmuseum_Düsseldorf"]}}'::jsonb)
WHERE slug = 'filmmuseum-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Kom(m)ödchen** ist eine Kabarettbühne in der Düsseldorfer Altstadt, gegründet als politisch-literarisches Kabarett. Kay und Lore Lorentz riefen es **1947** im Hinterzimmer einer Kneipe ins Leben, das erste Programm „positiv dagegen“ hatte im März 1947 Premiere.

Weil es im alten Haus an der Hunsrückenstraße zu eng wurde, bot die Stadt Räume in der damals neu gebauten **Kunsthalle** an, in die das Kabarett im April **1967** umzog. Nach dem Tod von Kay Lorentz übernahm Lore Lorentz 1993 die künstlerische Leitung, sie starb im Februar 1994. Der Eingang liegt am **Kay-und-Lore-Lorentz-Platz**, der Saal hat 200 Plätze.

Neben dem **eigenen Ensemble** treten Gäste aus der deutschsprachigen Kabarettszene auf, auch Newcomer. Aus den Ensembles des Hauses gingen unter anderem Hugo Egon Balder, Volker Pispers und Harald Schmidt hervor. Von der Stadtbahn-Haltestelle **Heinrich-Heine-Allee** sind es rund zwei Minuten zu Fuß.$txt$, webseite = COALESCE(webseite, 'https://www.kommoedchen.de'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Kom(m)%C3%B6dchen", "https://www.kommoedchen.de/theater/", "https://www.kommoedchen.de/theater/", "https://www.kommoedchen.de/theater/", "https://www.kommoedchen.de/theater/", "https://www.kommoedchen.de/theater/", "https://www.kommoedchen.de/theater/", "https://www.kommoedchen.de/kontakt/"]}}'::jsonb)
WHERE slug = 'kom-m-oedchen-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Der **Kunstpalast** ist das städtische Kunstmuseum Düsseldorfs und liegt zwischen Rhein und **Hofgarten** nördlich der Altstadt. Seine Geschichte beginnt **1846** mit einem Verein zur Errichtung einer Gemäldegalerie, der vor allem Werke der Düsseldorfer Malerschule ankaufte. Ein eigenes Kunstmuseum der Stadt öffnete erst 1928.

Das Gebäude gehört zum **Ehrenhof**, den Wilhelm Kreis 1925/26 für die Großausstellung **GeSoLei** plante und der den älteren Ausstellungsbau Kunstpalast von 1902 einbezog. Das Ensemble umschließt mit Kunstpalast und NRW-Forum einen Innenhof und zieht sich über ein Gartenparterre bis zur Tonhalle. Von 1999 bis 2000 entstand hinter der denkmalgeschützten Fassade ein Neubau nach Entwurf von **Oswald Mathias Ungers**. Seit 2020 gehört das benachbarte NRW-Forum zum Kunstpalast.

Die Sammlung umfasst über 100.000 Objekte, darunter Gemälde und Skulpturen vom Mittelalter bis zur Gegenwart sowie Kunstgewerbe, Design, Grafik und Fotografie. Zum Haus gehört auch das **Glasmuseum Hentrich** mit einer bedeutenden Glassammlung. Die **Graphische Sammlung** bewahrt über 90.000 Zeichnungen, Aquarelle und Druckgrafiken aus acht Jahrhunderten.$txt$, webseite = COALESCE(webseite, 'https://www.kunstpalast.de'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Museum_Kunstpalast", "https://de.wikipedia.org/wiki/Museum_Kunstpalast", "https://de.wikipedia.org/wiki/Museum_Kunstpalast", "https://de.wikipedia.org/wiki/Museum_Kunstpalast", "https://de.wikipedia.org/wiki/Ehrenhof_(D%C3%BCsseldorf)", "https://de.wikipedia.org/wiki/Museum_Kunstpalast", "https://de.wikipedia.org/wiki/Museum_Kunstpalast", "https://de.wikipedia.org/wiki/Museum_Kunstpalast", "https://de.wikipedia.org/wiki/Museum_Kunstpalast", "https://de.wikipedia.org/wiki/Museum_Kunstpalast"]}}'::jsonb)
WHERE slug = 'kunstpalast-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die **Mitsubishi Electric Halle** ist eine Mehrzweckhalle in **Oberbilk**, in der Konzerte, Shows und Sportveranstaltungen stattfinden. Eröffnet wurde sie **1971** unter dem Namen **Philipshalle**, seit 2011 trägt sie den Namen ihres heutigen Sponsors. Die Halle gehört der Stadt Düsseldorf und wird von der **D.LIVE** betrieben.

Der Innenraum umfasst rund **3.300 Quadratmeter** und fasst bis zu **7.500** Menschen. Ausfahrbare Tribünen und ein Vorhangsystem erlauben unterschiedliche Aufteilungen des Saals. Dazu kommen zwei **Foyers** mit jeweils rund 900 Quadratmetern und eine Außenterrasse.

Die Halle liegt an der Siegburger Straße direkt neben dem **Volksgarten**. Die nächste Haltestelle ist **Oberbilk S U**, die von Stadtbahn und S-Bahn angefahren wird und nur wenige Gehminuten entfernt liegt.$txt$, webseite = COALESCE(webseite, 'https://www.mitsubishi-electric-halle.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Mitsubishi_Electric_Halle", "https://de.wikipedia.org/wiki/Mitsubishi_Electric_Halle", "https://de.wikipedia.org/wiki/Mitsubishi_Electric_Halle", "https://www.mitsubishi-electric-halle.de/veranstalter/raumuebersicht", "https://www.mitsubishi-electric-halle.de/veranstalter/raumuebersicht", "https://www.mitsubishi-electric-halle.de/veranstalter/raumuebersicht", "https://de.wikipedia.org/wiki/Mitsubishi_Electric_Halle", "https://www.mitsubishi-electric-halle.de/besucherinfos/anfahrt"]}}'::jsonb)
WHERE slug = 'mitsubishi-electric-halle' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Opernhaus Düsseldorf** an der Heinrich-Heine-Allee ist Spielstätte und Verwaltungssitz der **Deutschen Oper am Rhein**. Es liegt am Rand der Altstadt zwischen **Hofgarten** und Königsallee. Die Deutsche Oper am Rhein ist eine Theatergemeinschaft der Städte Düsseldorf und Duisburg, wurde 1956 gegründet und umfasst neben der Oper auch die Compagnie Ballett am Rhein.

Das Gebäude wurde **1875** als Stadttheater nach Plänen von Ernst Giese im Stil der italienischen Renaissance eröffnet. Bei Luftangriffen 1943 wurde es stark beschädigt. Von 1954 bis 1956 bauten Paul Bonatz, Julius Schulte-Frohlinde und Ernst Huhn das Haus grundlegend um und gaben ihm sein heutiges Erscheinungsbild. Seit **1994** steht es unter Denkmalschutz.

Bei einer Sanierung 2006/2007 kam ein Orchester- und Ballettprobensaal mit zehn Meter breiter Glasfassade zum Hofgarten hinzu. Im Keller lagert der **Fundus** mit rund 50.000 Kostümen. Nächste Haltestelle ist **Heinrich-Heine-Allee**, vom Hauptbahnhof sind es drei U-Bahn-Stationen.$txt$, webseite = COALESCE(webseite, 'https://www.operamrhein.de'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Opernhaus_D%C3%BCsseldorf_(1943)", "https://www.operamrhein.de/ihr-besuch/opernhaus-duesseldorf/", "https://www.operamrhein.de/ueber-uns/", "https://www.operamrhein.de/ihr-besuch/opernhaus-duesseldorf/", "https://www.operamrhein.de/ihr-besuch/opernhaus-duesseldorf/", "https://de.wikipedia.org/wiki/Opernhaus_D%C3%BCsseldorf_(1943)", "https://de.wikipedia.org/wiki/Opernhaus_D%C3%BCsseldorf_(1943)", "https://www.operamrhein.de/ihr-besuch/opernhaus-duesseldorf/", "https://www.operamrhein.de/ihr-besuch/opernhaus-duesseldorf/", "https://www.operamrhein.de/ihr-besuch/opernhaus-duesseldorf/"]}}'::jsonb)
WHERE slug = 'opernhaus-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die **Stadtteilbücherei Bilk** ist eine Filiale der Stadtbüchereien Düsseldorf an der **Friedrichstraße 127**. Sie befindet sich in den **Düsseldorf Arkaden**. Auf rund 440 Quadratmetern verteilt sich das Angebot über zwei Etagen.

Neben Büchern, Hörbüchern, DVDs und Spielen gibt es eine **Kinder- und Jugendbibliothek**, ein Lesecafé und Arbeitsplätze. Eine Besonderheit ist die **Bibliothek der Dinge**, in der Gegenstände statt Medien ausgeliehen werden. Regelmäßig finden Lesungen, Workshops und **Kamishibai**-Erzählstunden für Kinder statt.$txt$, webseite = COALESCE(webseite, 'https://www.duesseldorf.de/stadtbuechereien/standorte/bilk'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.duesseldorf.de/stadtbuechereien/standorte/bilk", "https://www.ddorf-aktuell.de/?p=99758", "https://www.duesseldorf.de/stadtbuechereien/standorte/bilk", "https://www.duesseldorf.de/stadtbuechereien/standorte/bilk", "https://www.duesseldorf.de/stadtbuechereien/standorte/bilk", "https://www.duesseldorf.de/stadtbuechereien/standorte/bilk"]}}'::jsonb)
WHERE slug = 'stadtbuecherei-bilk' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Tanzhaus NRW** ist ein Zentrum für zeitgenössischen Tanz und zugleich Spielort, Produktionsort und Akademie. Seine Anfänge reichen bis **1973** zurück, als eine Gruppe Düsseldorfer Künstlerinnen und Künstler den Grundstein legte, und 1978 entstand die „Werkstatt“, aus der das Haus hervorging. Seit **1998** ist es in einem alten Straßenbahndepot an der Erkrather Straße 30 untergebracht.

Auf rund 4.000 Quadratmetern gibt es zwei Bühnen sowie acht Tanz- und Probenstudios. Der **Große Saal** hat 318 Sitzplätze, der Kleine Saal 89. Als Produktionshaus für freischaffende Choreografinnen und Choreografen nimmt das Haus jedes Jahr Künstlerinnen, Künstler und Ensembles für Residenzen, Labs und Workshops auf. Das **Junge Tanzhaus** widmet sich dem Tanz für und mit jungem Publikum.

Die Akademie richtet sich an alle Generationen, rund 80 Dozentinnen und Dozenten unterrichten Stile von Urban Dance über zeitgenössischen Tanz bis Tap. Jeden Morgen findet ein **Professional Training** für Tanzschaffende statt. Die Haltestelle **Worringer Platz** liegt etwa fünf Gehminuten entfernt, der Hauptbahnhof rund zehn.$txt$, webseite = COALESCE(webseite, 'https://tanzhaus-nrw.de'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://tanzhaus-nrw.de/de/haus/profil", "https://tanzhaus-nrw.de/de/haus/profil", "https://de.wikipedia.org/wiki/Tanzhaus_NRW", "https://tanzhaus-nrw.de/de/haus/profil", "https://tanzhaus-nrw.de/de/haus/profil", "https://tanzhaus-nrw.de/de/haus/profil", "https://tanzhaus-nrw.de/de/haus/profil", "https://tanzhaus-nrw.de/de/haus/profil", "https://tanzhaus-nrw.de/de/haus/profil", "https://tanzhaus-nrw.de/de/dein-besuch"]}}'::jsonb)
WHERE slug = 'tanzhaus-nrw' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die **Tonhalle** ist ein Konzerthaus am Rheinufer in Pempelfort und bildet den südlichen Abschluss des Kulturforums **Ehrenhof**. Der Rundbau entstand 1925/26 nach Plänen von **Wilhelm Kreis** als Mehrzweckhalle für die Ausstellung GeSoLei und hieß zunächst Rheinhalle. Das Gebäude war von Anfang an so angelegt, dass es auch als **Planetarium** dienen konnte.

Nach Kriegsschäden baute das Architekturbüro **HPP** um Helmut Hentrich von 1976 bis **1978** unter der rekonstruierten Kuppel einen fast halbkugelförmigen Konzertsaal ein. Im Jahr 2005 wurde das Haus erneut modernisiert. Der große Saal heißt seit 2014 **Mendelssohn-Saal** und hat 1.854 Plätze, dazu kommen ein Kammermusiksaal mit 300 Plätzen und die Rotunde im Foyer.

Die Tonhalle ist die Heimat der **Düsseldorfer Symphoniker**. Neben Klassik stehen auch Jazz und Kabarett auf dem Programm. In der Nähe liegt der U-Bahnhof **Tonhalle/Ehrenhof**.$txt$, webseite = COALESCE(webseite, 'https://www.tonhalle.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Tonhalle_Düsseldorf", "https://de.wikipedia.org/wiki/Tonhalle_Düsseldorf", "https://de.wikipedia.org/wiki/Tonhalle_Düsseldorf", "https://de.wikipedia.org/wiki/Tonhalle_Düsseldorf", "https://www.visitduesseldorf.de/attraktionen/tonhalle-duesseldorf-concert-hall-9b4f1d13f7", "https://de.wikipedia.org/wiki/Tonhalle_Düsseldorf", "https://de.wikipedia.org/wiki/Tonhalle_Düsseldorf", "https://www.visitduesseldorf.de/attraktionen/tonhalle-duesseldorf-concert-hall-9b4f1d13f7", "https://de.wikipedia.org/wiki/Tonhalle_Düsseldorf"]}}'::jsonb)
WHERE slug = 'tonhalle-duesseldorf' AND typ = 'spielstaette';

COMMIT;

-- Kontrolle: Ortsseiten mit freigegebenem Text
SELECT count(*) FILTER (WHERE extras->'spielstaette' ? 'text_freigegeben') AS mit_text,
       count(*) AS spielstaetten FROM public.orte WHERE typ = 'spielstaette';
